// fax-receipts — proof that a records request arrived, and the clock that starts when it did.
//
// THERE ARE TWO DIFFERENT RECEIPTS AND THEY PROVE DIFFERENT THINGS. Conflating them is how you
// end up telling a judge you have proof of service when what you have is proof of dialling.
//
//   1. THE TRANSMISSION REPORT. Generated by the sending machine or the provider API. It proves
//      the pages left, how many, when, and which remote machine answered (the CSID). It does NOT
//      prove a human read it, that the pages were legible, or that the request was logged.
//
//   2. THE AGENCY ACKNOWLEDGEMENT. A letter, email or portal entry from the body itself, with
//      its own reference number. This is the one that proves RECEIPT -- and receipt is what
//      Tex. Gov't Code § 552.301(b) counts from. It is also the thing the cover sheet in
//      fax-system asks for by name.
//
// So the ledger tracks both, separately, and never lets one stand in for the other. An entry with
// a transmission report and no acknowledgement is `sent-unacknowledged`, which is a real and
// slightly precarious state, not a finished one.
//
// House rules: ESM, soft-fail-never-throw, no network in this module -- the Gmail/provider calls
// happen in the caller, and the classifiers here are pure so they can be tested offline.

import * as bh from './business-hours.mjs';

const str = (v) => String(v == null ? '' : v);
const now = () => new Date().toISOString();
const day = (v) => str(v).slice(0, 10);

// ---------------------------------------------------------------------------
// 1. WHAT MAKES A TRANSMISSION REPORT EVIDENCE
//
// A photograph of a screen saying "Sent" is not a record. These are the fields a report needs
// before it is worth attaching to a motion, and the ledger says which are missing rather than
// pretending a thin report is a good one.
// ---------------------------------------------------------------------------

export const REPORT_FIELDS = Object.freeze([
  { key: 'atISO', label: 'date and time of transmission', weight: 'required' },
  { key: 'toFax', label: 'the number dialled', weight: 'required' },
  { key: 'result', label: 'result (OK / failed / busy / no answer)', weight: 'required' },
  { key: 'pages', label: 'pages transmitted', weight: 'required' },
  { key: 'durationSec', label: 'connection duration', weight: 'strong' },
  { key: 'remoteId', label: 'remote CSID — the answering machine identifying itself', weight: 'strong' },
  { key: 'fromFax', label: 'the sending number', weight: 'useful' },
  { key: 'provider', label: 'provider or machine that produced the report', weight: 'useful' },
]);

export const OK_RESULTS = Object.freeze(['ok', 'success', 'delivered', 'sent', 'complete']);

export function isSuccessful(result) {
  return OK_RESULTS.includes(str(result).trim().toLowerCase());
}

/** Grade a transmission report. Returns what is present, what is missing, and whether it is usable. */
export function gradeReport(report = {}) {
  const have = [];
  const missing = [];
  for (const f of REPORT_FIELDS) {
    (str(report[f.key]).trim() || typeof report[f.key] === 'number' ? have : missing).push(f);
  }
  const missingRequired = missing.filter((f) => f.weight === 'required');
  return {
    usable: missingRequired.length === 0 && isSuccessful(report.result),
    complete: missing.length === 0,
    have: have.map((f) => f.key),
    missing: missing.map((f) => ({ key: f.key, label: f.label, weight: f.weight })),
    verdict: missingRequired.length
      ? `Not yet evidence — missing ${missingRequired.map((f) => f.label).join(', ')}.`
      : !isSuccessful(report.result)
        ? `Records a ${str(report.result) || 'non-success'} result. This is proof the send FAILED, `
          + 'which is worth keeping — it is the basis for resending without losing the earlier attempt.'
        : missing.length
          ? 'Usable. Stronger with ' + missing.map((f) => f.label).join(', ') + '.'
          : 'Complete.',
  };
}

// ---------------------------------------------------------------------------
// 2. THE LEDGER
// ---------------------------------------------------------------------------

export const STATES = Object.freeze({
  AWAITING: 'awaiting-transmission',        // queued or held; nothing has gone down a line
  FAILED: 'transmission-failed',            // the report says busy / no answer / error
  SENT: 'sent-unacknowledged',              // pages left, nobody has confirmed receipt
  ACKED: 'acknowledged',                    // the body confirmed receipt in writing
  ANSWERED: 'answered',                     // records produced, or a ruling sought
});

export function createLedger(initial = []) {
  const rows = Array.isArray(initial) ? initial.map(normalize).filter(Boolean) : [];

  const api = {
    get size() { return rows.length; },
    all: () => rows.slice(),
    find: (id) => rows.find((r) => r.id === str(id)) || null,

    /** Open a ledger row when a job is queued, before anything is sent. */
    open({ id, to, fax, subject, pages = 1, regime = 'TX_PIA', days = 10, tz } = {}) {
      if (!str(id)) return null;
      const existing = api.find(id);
      if (existing) return existing;
      const row = normalize({
        id, to, fax, subject, pages, regime, days, tz,
        state: STATES.AWAITING, openedAt: now(), events: [],
      });
      rows.push(row);
      return row;
    },

    /**
     * Record a transmission. `method` says how it was sent, because a fax walked to a machine at
     * a UPS Store is a legitimate send and the ledger should be able to hold it.
     */
    recordTransmission(id, { report = {}, method = 'api', note = '' } = {}) {
      const row = api.find(id);
      if (!row) return null;
      const grade = gradeReport(report);
      row.report = { ...report, method, grade };
      row.attempts += 1;
      if (grade.usable) {
        row.state = STATES.SENT;
        row.sentAt = str(report.atISO) || now();
        row.clock = clockFor(row);
      } else if (str(report.result) && !isSuccessful(report.result)) {
        row.state = STATES.FAILED;
      }
      row.events.push({
        at: now(), kind: 'transmission', method,
        result: str(report.result), usable: grade.usable, note: str(note),
      });
      return row;
    },

    /**
     * Record the body's own acknowledgement. THIS is the receipt that matters -- and if the body
     * states a receipt date different from our send date, THEIRS governs the clock, because
     * § 552.301(b) counts from the date the body received the request.
     */
    recordAcknowledgement(id, { atISO = '', receivedISO = '', ref = '', from = '', note = '' } = {}) {
      const row = api.find(id);
      if (!row) return null;
      row.ack = {
        at: str(atISO) || now(),
        received: day(receivedISO) || day(row.sentAt),
        ref: str(ref), from: str(from),
        disputesOurDate: !!(day(receivedISO) && day(row.sentAt) && day(receivedISO) !== day(row.sentAt)),
      };
      row.state = STATES.ACKED;
      row.clock = clockFor(row);
      row.events.push({ at: now(), kind: 'acknowledgement', ref: str(ref), note: str(note) });
      return row;
    },

    recordResponse(id, { atISO = '', kind = 'records', note = '' } = {}) {
      const row = api.find(id);
      if (!row) return null;
      row.answeredAt = str(atISO) || now();
      row.state = STATES.ANSWERED;
      row.events.push({ at: now(), kind: `response:${str(kind)}`, note: str(note) });
      return row;
    },

    byState: (s) => rows.filter((r) => r.state === str(s)),
    toJSON: () => rows.slice(),
  };
  return api;
}

function normalize(raw) {
  if (!raw || !str(raw.id)) return null;
  const row = {
    id: str(raw.id), to: str(raw.to), fax: str(raw.fax), subject: str(raw.subject),
    pages: Number(raw.pages) || 1,
    regime: str(raw.regime) || 'TX_PIA', days: Number(raw.days) || 10,
    tz: str(raw.tz) || bh.DEFAULT_HOURS.tz,
    state: str(raw.state) || STATES.AWAITING,
    attempts: Number(raw.attempts) || 0,
    openedAt: str(raw.openedAt) || now(),
    sentAt: str(raw.sentAt), answeredAt: str(raw.answeredAt),
    report: raw.report || null, ack: raw.ack || null, clock: raw.clock || null,
    events: Array.isArray(raw.events) ? raw.events.slice() : [],
  };
  if (row.sentAt && !row.clock) row.clock = clockFor(row);
  return row;
}

/**
 * The statutory clock. Counts from the ACKNOWLEDGED receipt date if the body gave one, otherwise
 * from our transmission date -- and says which, because the difference is exactly what a body
 * will argue about.
 */
export function clockFor(row) {
  const from = (row.ack && row.ack.received) || day(row.sentAt);
  if (!from) return null;
  const regime = str(row.regime).startsWith('US_') || row.regime === 'FOIA' ? 'FEDERAL' : 'TX_PIA';
  const r = bh.addBusinessDays(from, Number(row.days) || 10, { regime });
  if (!r) return null;
  return {
    from,
    basis: row.ack && row.ack.received ? "the body's own stated receipt date" : 'our transmission report',
    due: r.date,
    days: Number(row.days) || 10,
    exact: false,
    caveat: r.caveat,
    skipped: r.skipped,
  };
}

// ---------------------------------------------------------------------------
// 3. TRIAGE
// ---------------------------------------------------------------------------

export function triage(ledger, asOfISO = now()) {
  const rows = typeof ledger?.all === 'function' ? ledger.all() : (Array.isArray(ledger) ? ledger : []);
  const asOf = day(asOfISO);
  const out = {
    awaitingTransmission: [], failed: [], sentUnacknowledged: [],
    acknowledged: [], overdue: [], answered: [],
  };
  for (const r of rows) {
    if (r.state === STATES.ANSWERED) { out.answered.push(r); continue; }
    if (r.state === STATES.AWAITING) { out.awaitingTransmission.push(r); continue; }
    if (r.state === STATES.FAILED) { out.failed.push(r); continue; }
    const overdue = r.clock && r.clock.due < asOf;
    if (overdue) out.overdue.push(r);
    else if (r.state === STATES.ACKED) out.acknowledged.push(r);
    else out.sentUnacknowledged.push(r);
  }
  const byDue = (a, b) => str(a.clock?.due).localeCompare(str(b.clock?.due));
  out.overdue.sort(byDue); out.sentUnacknowledged.sort(byDue); out.acknowledged.sort(byDue);
  return out;
}

/** What a § 552.302 argument needs, stated only where it is actually available. */
export function lateNotice(row, asOfISO = now()) {
  if (!row || !row.clock) return null;
  if (row.clock.due >= day(asOfISO)) return null;
  const proof = row.ack ? "the body's own acknowledgement" : (row.report?.grade?.usable ? 'the transmission report' : null);
  return {
    id: row.id, to: row.to, due: row.clock.due, from: row.clock.from, basis: row.clock.basis,
    provable: !!proof,
    proof,
    argument: proof
      ? 'Tex. Gov\'t Code § 552.302: a governmental body that does not request an attorney general '
        + 'ruling within ten business days loses its exceptions, and the information is presumed '
        + 'public absent a compelling demonstration.'
      : 'NOT YET ARGUABLE — the receipt date is not provable. Obtain the transmission report or a '
        + 'written acknowledgement before asserting the body is late.',
    caveat: row.clock.caveat,
  };
}

// ---------------------------------------------------------------------------
// 4. CLASSIFIERS — pure, so the Gmail sweep can be tested offline
//
// Two things arrive by email and both are receipts: the fax provider's confirmation, and the
// agency's acknowledgement. These recognise them from message-shaped objects
// ({ from, subject, body, date }) without doing any I/O.
// ---------------------------------------------------------------------------

const PROVIDER_HINTS = [
  'telnyx', 'clicksend', 'phaxio', 'efax', 'srfax', 'humblefax', 'faxzero', 'metrofax',
  'ringcentral', 'hellofax', 'fax.plus', 'gotfreefax', 'westfax',
];

export function classifyMessage(msg = {}) {
  const from = str(msg.from).toLowerCase();
  const subject = str(msg.subject).toLowerCase();
  const body = str(msg.body);
  const low = `${subject} ${body.toLowerCase()}`;

  const providerish = PROVIDER_HINTS.some((h) => from.includes(h) || subject.includes(h));
  const faxWord = /\bfax\b/.test(low);

  if ((providerish || faxWord) && /(transmission|confirmation|receipt|delivered|sent successfully|status)/.test(low)) {
    return {
      kind: 'transmission-confirmation',
      provider: PROVIDER_HINTS.find((h) => from.includes(h) || subject.includes(h)) || 'unknown',
      result: /(fail|error|busy|no answer|unable)/.test(low) ? 'failed' : 'ok',
      pages: numAfter(body, /pages?\D{0,12}(\d{1,3})/i),
      toFax: (body.match(/\+?1?[\s.-]?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}/) || [])[0] || '',
      confidence: providerish ? 'high' : 'low',
    };
  }

  if (/(public information|open records|records request|foia|pia)/.test(low)
      && /(receiv|acknowledg|assigned|reference|request (no|number)|tracking)/.test(low)) {
    return {
      kind: 'agency-acknowledgement',
      ref: (body.match(/\b([A-Z]{1,4}[-# ]?\d{4,}[-\d]*)\b/) || [])[1] || '',
      from: str(msg.from),
      receivedISO: day(msg.date),
      confidence: /acknowledg|received your/.test(low) ? 'high' : 'low',
    };
  }

  return { kind: 'other', confidence: 'n/a' };
}

function numAfter(text, re) {
  const m = re.exec(str(text));
  return m ? Number(m[1]) : undefined;
}

/** Gmail search strings for the caller. Kept here so the vocabulary lives with the classifier. */
export const GMAIL_QUERIES = Object.freeze({
  transmissions: `newer_than:60d (${PROVIDER_HINTS.slice(0, 8).map((h) => `from:${h}`).join(' OR ')} `
    + 'OR subject:fax OR "transmission report" OR "fax confirmation")',
  acknowledgements: 'newer_than:60d ("public information act" OR "open records" OR "records request" '
    + 'OR FOIA) (acknowledg OR "we have received" OR "assigned" OR "reference number")',
});

// ---------------------------------------------------------------------------
// 5. REPORTING
// ---------------------------------------------------------------------------

export function report(ledger, asOfISO = now()) {
  const t = triage(ledger, asOfISO);
  const line = (r) => `  ${str(r.id).padEnd(34)} ${str(r.to).slice(0, 34).padEnd(36)}`
    + `${r.clock ? `due ${r.clock.due}` : 'no clock'}`;
  const out = [`Fax receipts as of ${day(asOfISO)}`, ''];
  const sections = [
    ['OVERDUE — § 552.302 available if receipt is provable', t.overdue],
    ['ACKNOWLEDGED, awaiting production', t.acknowledged],
    ['SENT, no acknowledgement yet', t.sentUnacknowledged],
    ['TRANSMISSION FAILED — resend', t.failed],
    ['NOT YET SENT', t.awaitingTransmission],
    ['ANSWERED', t.answered],
  ];
  for (const [title, list] of sections) {
    if (!list.length) continue;
    out.push(`${title} (${list.length})`);
    for (const r of list) out.push(line(r));
    out.push('');
  }
  if (out.length === 2) out.push('  (ledger is empty)');
  return out.join('\n');
}

export function handler(req, res) {
  const url = new URL(req.url || '/', 'http://localhost');
  const send = (code, obj) => {
    res.statusCode = code;
    res.setHeader('content-type', 'application/json; charset=utf-8');
    res.end(JSON.stringify(obj, null, 2));
  };
  if (url.pathname.endsWith('/fields')) return send(200, { ok: true, fields: REPORT_FIELDS });
  if (url.pathname.endsWith('/queries')) return send(200, { ok: true, queries: GMAIL_QUERIES });
  return send(200, {
    ok: true, service: 'fax-receipts',
    routes: ['/fields', '/queries'],
    note: 'The ledger is caller-held state. Import createLedger() — there is no server-side store.',
  });
}
